                    "script": ";(function () {  const emailInputSelector = '#{{hrid}} #sw-form-capture-email-input';  const submitButtonSelector = '#{{hrid}} #sw-forgot-password-submit-btn';  const confirmationMessage = '#{{hrid}} .confirmation-message';  const form = '#{{hrid}} #forgot-password .fields';  const errorMessage = '#{{hrid}} .other-errors';  const appId = $('body > div.content').attr('data-appid');   $('#{{hrid}} input').keyup((evt) => {   if ( evt.which === 13 ) {    evt.preventDefault();    $(submitButtonSelector).click();   }  });   function isEmail(email) {   const emailReg = /^(([^<>()[\\]\\\\.,;:\\s@\\\"]+(\\.[^<>()[\\]\\\\.,;:\\s@\\\"]+)*)|(\\\".+\\\"))@((\\[[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\])|(([a-zA-Z\\-0-9]+\\.)+[a-zA-Z]{2,}))$/;   return email && emailReg.test(email);  }   function handleSuccess() {   setTimeout(function () {    $(submitButtonSelector + ' .sw-btn-spinner').addClass('d-none');    $(form).addClass('d-none');    $(confirmationMessage).removeClass('d-none');    $(emailInputSelector).val('');   }, 100);  }   function getApiBaseUrl() {   if(window.location.href.startsWith('file:///') ||    window.location.href.startsWith('http://localhost:')) {    return 'http://localhost:8081';   } else {    return 'https://' + window.location.hostname;   }  }   function makeForgotPasswordRequest(email, successCallback, errorCallback) {   const apiBaseUrl = getApiBaseUrl();    const url = apiBaseUrl + '/v1/applications/' + appId + '/users/forgot-password-requests';   $.ajax({    url: url,    type: 'POST',    data: JSON.stringify({email: email}),    contentType: 'application/json; charset=utf-8',    success: function (data) {     successCallback();    },    error: function (error) {     console.log(error);     errorCallback(error);    }   });  }   $(submitButtonSelector).click(function (e) {   e.preventDefault();   const email = $(emailInputSelector).val().trim();    /* validate the input */   $(emailInputSelector).removeClass('sw-input-invalid');   if (!isEmail(email)) {    $(emailInputSelector).addClass('sw-input-invalid');    return   }    $(submitButtonSelector + ' .sw-btn-spinner').removeClass('d-none');    makeForgotPasswordRequest(email, handleSuccess, handleFailure);  });   function handleFailure(data) {   if(data.status >= 400) {    $(errorMessage).addClass('d-block');   }else {    $(errorMessage).removeClass('d-block');   }   $(emailInputSelector).addClass('sw-input-invalid');   $(submitButtonSelector + ' .sw-btn-spinner').addClass('d-none');  } })(); ",
